const awayTeam = $('Parse Teams').item.json.away_team || '';
const homeTeam = $('Parse Teams').item.json.home_team || '';
const gameDate = $('Parse Teams').item.json.game_date || '';

// --- Odds data ---
let oddsData = [];
try {
  oddsData = $('Get NCAAF Odds').all().map(i => i.json) || [];
} catch(e) { oddsData = []; }

// Find matching game and compute avg odds
const isGeneral = awayTeam.toLowerCase() === 'general' || homeTeam.toLowerCase() === 'general';
let matchedGame = null;
let awayOdds = [];
let homeOdds = [];

if (!isGeneral) {
  for (const game of oddsData) {
    const at = (game.away_team || '').toLowerCase();
    const ht = (game.home_team || '').toLowerCase();
    if (at.includes(awayTeam.toLowerCase()) || ht.includes(homeTeam.toLowerCase()) ||
        awayTeam.toLowerCase().includes(at) || homeTeam.toLowerCase().includes(ht)) {
      matchedGame = game;
      for (const bookie of (game.bookmakers || [])) {
        for (const market of (bookie.markets || [])) {
          if (market.key === 'h2h') {
            for (const outcome of (market.outcomes || [])) {
              if ((outcome.name || '').toLowerCase().includes(awayTeam.toLowerCase()) ||
                  awayTeam.toLowerCase().includes((outcome.name || '').toLowerCase())) {
                awayOdds.push(outcome.price);
              } else {
                homeOdds.push(outcome.price);
              }
            }
          }
        }
      }
      break;
    }
  }
}

const avg = arr => arr.length ? Math.round(arr.reduce((a,b) => a+b, 0) / arr.length) : null;
const awayAvg = avg(awayOdds);
const homeAvg = avg(homeOdds);

let favoriteTeam = 'Unknown', underdogTeam = 'Unknown', favoriteOdds = null, underdogOdds = null;
if (awayAvg !== null && homeAvg !== null) {
  if (awayAvg < homeAvg) {
    favoriteTeam = awayTeam; favoriteOdds = awayAvg;
    underdogTeam = homeTeam; underdogOdds = homeAvg;
  } else {
    favoriteTeam = homeTeam; favoriteOdds = homeAvg;
    underdogTeam = awayTeam; underdogOdds = awayAvg;
  }
}

// --- ESPN News ---
let newsHeadlines = [];
try {
  const newsItems = $('ESPN NCAAFB News').first().json?.articles || [];
  newsHeadlines = newsItems.slice(0, 3).map(a => a.headline || a.title || '');
} catch(e) { newsHeadlines = []; }

// --- ESPN Scoreboard: find matching game for rankings/records ---
let gameContext = {};
try {
  const events = $('ESPN NCAAFB Scoreboard').first().json?.events || [];
  for (const event of events) {
    const competitors = event?.competitions?.[0]?.competitors || [];
    const names = competitors.map(c => (c.team?.displayName || c.team?.shortDisplayName || '').toLowerCase());
    if (!isGeneral && (names.some(n => n.includes(awayTeam.toLowerCase()) || awayTeam.toLowerCase().includes(n)) ||
        names.some(n => n.includes(homeTeam.toLowerCase()) || homeTeam.toLowerCase().includes(n)))) {
      gameContext.status = event?.status?.type?.description || '';
      gameContext.competitors = competitors.map(c => ({
        name: c.team?.displayName || '',
        rank: c.curatedRank?.current || null,
        record: c.records?.[0]?.summary || '',
        homeAway: c.homeAway || ''
      }));
      gameContext.venue = event?.competitions?.[0]?.venue?.fullName || '';
      gameContext.neutralSite = event?.competitions?.[0]?.neutralSite || false;
      break;
    }
  }
} catch(e) { gameContext = {}; }

return [{
  json: {
    away_team: awayTeam,
    home_team: homeTeam,
    game_date: gameDate,
    away_avg_american: awayAvg,
    home_avg_american: homeAvg,
    favorite_team: favoriteTeam,
    favorite_odds: favoriteOdds,
    underdog_team: underdogTeam,
    underdog_odds: underdogOdds,
    matched_game: matchedGame ? { away: matchedGame.away_team, home: matchedGame.home_team, commence: matchedGame.commence_time } : null,
    news_headlines: newsHeadlines,
    game_context: gameContext
  }
}];
